1. use clap::Parser;
2. use cli_config::{App, Commands, EncodeArgs};
3. use translators::decode::{decode_token, print_decoded_token};
4. use translators::encode::{encode_token, print_encoded_token};
5. 
6. pub mod cli_config;
7. pub mod translators;
8. pub mod utils;
9. 
10. fn warn_unsupported(arguments: &EncodeArgs) {
11.     if arguments.typ.is_some() {
12.         println!("Sorry, `typ` isn't supported quite yet!");
13.     };
14. }
15. 
16. fn main() {
17.     let app = App::parse();
18.     // let matches = config_options().get_matches();
19. 
20.     match &app.command {
21.         Commands::Encode(arguments) => {
22.             warn_unsupported(arguments);
23. 
24.             let token = encode_token(arguments);
25. 
26.             print_encoded_token(token);
27.         }
28.         Commands::Decode(arguments) => {
29.             let (validated_token, token_data, format) = decode_token(arguments);
30. 
31.             print_decoded_token(validated_token, token_data, format);
32.         }
33.     }
34. }
35.

