14. fn create_header(alg: Algorithm, kid: Option<&String>) -> Header {
15.     let mut header = Header::new(alg);
16. 
17.     header.kid = kid.map(|k| k.to_owned());
18. 
19.     header
20. }
21. 
22. pub fn encoding_key_from_secret(alg: &Algorithm, secret_string: &str) -> JWTResult<EncodingKey> {
23.     match alg {
24.         Algorithm::HS256 | Algorithm::HS384 | Algorithm::HS512 => {
25.             if secret_string.starts_with('@') {
26.                 let secret = slurp_file(&secret_string.chars().skip(1).collect::<String>());
27.                 Ok(EncodingKey::from_secret(&secret))
28.             } else if secret_string.starts_with("b64:") {
29.                 Ok(EncodingKey::from_secret(
30.                     &base64_engine
31.                         .decode(secret_string.chars().skip(4).collect::<String>())
32.                         .unwrap(),
33.                 ))
34.             } else {
35.                 Ok(EncodingKey::from_secret(secret_string.as_bytes()))
36.             }
37.         }
38.         Algorithm::RS256
39.         | Algorithm::RS384
40.         | Algorithm::RS512
41.         | Algorithm::PS256
42.         | Algorithm::PS384
43.         | Algorithm::PS512 => {
44.             let secret = slurp_file(&secret_string.chars().skip(1).collect::<String>());
45. 
46.             match secret_string.ends_with(".pem") {
47.                 true => EncodingKey::from_rsa_pem(&secret),
48.                 false => Ok(EncodingKey::from_rsa_der(&secret)),
49.             }
50.         }
51.         Algorithm::ES256 | Algorithm::ES384 => {
52.             let secret = slurp_file(&secret_string.chars().skip(1).collect::<String>());
53. 
54.             match secret_string.ends_with(".pem") {
55.                 true => EncodingKey::from_ec_pem(&secret),
56.                 false => Ok(EncodingKey::from_ec_der(&secret)),
57.             }
58.         }
59.     }
60. }
61. 
62. pub fn encode_token(arguments: &EncodeArgs) -> JWTResult<String> {
63.     let algorithm = translate_algorithm(&arguments.algorithm);
64.     let header = create_header(algorithm, arguments.kid.as_ref());
65.     let custom_payloads = arguments.payload.clone();
66.     let custom_payload = arguments
67.         .json
68.         .as_ref()
69.         .map(|value| {
70.             if value != "-" {
71.                 return String::from(value);
72.             }
73. 
74.             let mut buffer = String::new();
75. 
76.             io::stdin()
77.                 .read_line(&mut buffer)
78.                 .expect("STDIN was not valid UTF-8");
79. 
80.             buffer
81.         })
82.         .map(|raw_json| match from_str(&raw_json) {
83.             Ok(Value::Object(json_value)) => json_value
84.                 .into_iter()
85.                 .map(|(json_key, json_val)| Some(PayloadItem(json_key, json_val)))
86.                 .collect(),
87.             _ => panic!("Invalid JSON provided!"),
88.         });
89.     let now = Utc::now().timestamp();
90.     let expires = PayloadItem::from_timestamp_with_name(arguments.expires.as_ref(), "exp", now);
91.     let not_before =
92.         PayloadItem::from_timestamp_with_name(arguments.not_before.as_ref(), "nbf", now);
93.     let issued_at = match arguments.no_iat {
94.         true => None,
95.         false => PayloadItem::from_timestamp_with_name(Some(&now.to_string()), "iat", now),
96.     };
97.     let issuer = PayloadItem::from_string_with_name(arguments.issuer.as_ref(), "iss");
98.     let subject = PayloadItem::from_string_with_name(arguments.subject.as_ref(), "sub");
99.     let audience = PayloadItem::from_string_with_name(arguments.audience.as_ref(), "aud");
100.     let jwt_id = PayloadItem::from_string_with_name(arguments.jwt_id.as_ref(), "jti");
101.     let mut maybe_payloads: Vec<Option<PayloadItem>> = vec![
102.         issued_at, expires, issuer, subject, audience, jwt_id, not_before,
103.     ];
104. 
105.     maybe_payloads.append(&mut custom_payloads.unwrap_or_default());
106.     maybe_payloads.append(&mut custom_payload.unwrap_or_default());
107. 
108.     let payloads = maybe_payloads.into_iter().flatten().collect();
109.     let Payload(claims) = Payload::from_payloads(payloads);
110. 
111.     encoding_key_from_secret(&algorithm, &arguments.secret)
112.         .and_then(|secret| encode(&header, &claims, &secret))
113. }
114. 
115. pub fn print_encoded_token(token: JWTResult<String>) {
116.     match token {
117.         Ok(jwt) => {
118.             if atty::is(Stream::Stdout) {
119.                 println!("{}", jwt);
120.             } else {
121.                 print!("{}", jwt);
122.             }
123.             exit(0);
124.         }
125.         Err(err) => {
126.             bunt::eprintln!("{$red+bold}Something went awry creating the jwt{/$}\n");
127.             eprintln!("{}", err);
128.             exit(1);
129.         }
