44.                 Ok(DecodingKey::from_secret(&secret).into_static())
45.             } else if secret_string.starts_with("b64:") {
46.                 Ok(DecodingKey::from_secret(
47.                     &base64_engine
48.                         .decode(secret_string.chars().skip(4).collect::<String>())
49.                         .unwrap(),
50.                 )
51.                 .into_static())
52.             } else {
53.                 Ok(DecodingKey::from_secret(secret_string.as_bytes()).into_static())
54.             }
55.         }
56.         Algorithm::RS256
57.         | Algorithm::RS384
58.         | Algorithm::RS512
59.         | Algorithm::PS256
60.         | Algorithm::PS384
61.         | Algorithm::PS512 => {
62.             let secret = slurp_file(&secret_string.chars().skip(1).collect::<String>());
63. 
64.             match secret_string.ends_with(".pem") {
