66.                 false => Ok(DecodingKey::from_rsa_der(&secret).into_static()),
67.             }
68.         }
69.         Algorithm::ES256 | Algorithm::ES384 => {
70.             let secret = slurp_file(&secret_string.chars().skip(1).collect::<String>());
71. 
72.             match secret_string.ends_with(".pem") {
73.                 true => DecodingKey::from_ec_pem(&secret).map(DecodingKey::into_static),
74.                 false => Ok(DecodingKey::from_ec_der(&secret).into_static()),
75.             }
76.         }
77.     }
78. }
