80. pub fn decode_token(
81.     arguments: &DecodeArgs,
82. ) -> (
83.     JWTResult<TokenData<Payload>>,
84.     JWTResult<TokenData<Payload>>,
85.     OutputFormat,
86. ) {
87.     let algorithm = translate_algorithm(&arguments.algorithm);
88.     let secret = match arguments.secret.len() {
89.         0 => None,
90.         _ => Some(decoding_key_from_secret(&algorithm, &arguments.secret)),
91.     };
92.     let jwt = match arguments.jwt.as_str() {
93.         "-" => {
94.             let mut buffer = String::new();
95. 
96.             io::stdin()
97.                 .read_line(&mut buffer)
98.                 .expect("STDIN was not valid UTF-8");
99. 
100.             buffer
101.         }
102.         _ => arguments.jwt.clone(),
103.     }
104.     .trim()
