             println!("{}\n", to_string_pretty(&token.header).unwrap());
             bunt::println!("{$bold}Token claims\n------------{/$}");
             println!("{}", to_string_pretty(&token.claims).unwrap());
         }
         (_, Err(_)) => exit(1),
     }

     exit(match validated_token {
         Err(_) => 1,
         Ok(_) => 0,
     })
