pub mod errors {
    pub use jsonwebtoken8::errors::*;
}

use serde::Serialize;

pub use jsonwebtoken8::{Algorithm, Header, TokenData, Validation};

#[derive(Clone, Debug, PartialEq, Eq)]
enum KeyMaterial {
    SecretOrDer(Vec<u8>),
    Pem(Vec<u8>),
}

#[derive(Clone)]
pub struct EncodingKey {
    inner: jsonwebtoken8::EncodingKey,
    material: KeyMaterial,
}

impl PartialEq for EncodingKey {
    fn eq(&self, other: &Self) -> bool {
        self.material == other.material
    }
}

impl Eq for EncodingKey {}

impl std::fmt::Debug for EncodingKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("EncodingKey")
            .field("material", &self.material)
            .finish()
    }
}

impl EncodingKey {
    pub fn from_secret(secret: &[u8]) -> Self {
        EncodingKey {
            inner: jsonwebtoken8::EncodingKey::from_secret(secret),
            material: KeyMaterial::SecretOrDer(secret.to_vec()),
        }
    }

    pub fn from_rsa_pem(key: &[u8]) -> errors::Result<Self> {
        jsonwebtoken8::EncodingKey::from_rsa_pem(key).map(|inner| EncodingKey {
            inner,
            material: KeyMaterial::Pem(key.to_vec()),
        })
    }

    pub fn from_rsa_der(der: &[u8]) -> Self {
        EncodingKey {
            inner: jsonwebtoken8::EncodingKey::from_rsa_der(der),
            material: KeyMaterial::SecretOrDer(der.to_vec()),
        }
    }

    pub fn from_ec_pem(key: &[u8]) -> errors::Result<Self> {
        jsonwebtoken8::EncodingKey::from_ec_pem(key).map(|inner| EncodingKey {
            inner,
            material: KeyMaterial::Pem(key.to_vec()),
        })
    }

    pub fn from_ec_der(der: &[u8]) -> Self {
        EncodingKey {
            inner: jsonwebtoken8::EncodingKey::from_ec_der(der),
            material: KeyMaterial::SecretOrDer(der.to_vec()),
        }
    }

    pub fn from_ed_pem(key: &[u8]) -> errors::Result<Self> {
        jsonwebtoken8::EncodingKey::from_ed_pem(key).map(|inner| EncodingKey {
            inner,
            material: KeyMaterial::Pem(key.to_vec()),
        })
    }

    pub fn from_ed_der(der: &[u8]) -> Self {
        EncodingKey {
            inner: jsonwebtoken8::EncodingKey::from_ed_der(der),
            material: KeyMaterial::SecretOrDer(der.to_vec()),
        }
    }
}

#[derive(Clone)]
pub struct DecodingKey {
    inner: jsonwebtoken8::DecodingKey,
    material: KeyMaterial,
}

impl PartialEq for DecodingKey {
    fn eq(&self, other: &Self) -> bool {
        self.material == other.material
    }
}

impl Eq for DecodingKey {}

impl std::fmt::Debug for DecodingKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("DecodingKey")
            .field("material", &self.material)
            .finish()
    }
}

impl DecodingKey {
    pub fn from_secret(secret: &[u8]) -> Self {
        DecodingKey {
            inner: jsonwebtoken8::DecodingKey::from_secret(secret),
            material: KeyMaterial::SecretOrDer(secret.to_vec()),
        }
    }

    pub fn from_rsa_pem(key: &[u8]) -> errors::Result<Self> {
        jsonwebtoken8::DecodingKey::from_rsa_pem(key).map(|inner| DecodingKey {
            inner,
            material: KeyMaterial::Pem(key.to_vec()),
        })
    }

    pub fn from_rsa_der(der: &[u8]) -> Self {
        DecodingKey {
            inner: jsonwebtoken8::DecodingKey::from_rsa_der(der),
            material: KeyMaterial::SecretOrDer(der.to_vec()),
        }
    }

    pub fn from_ec_pem(key: &[u8]) -> errors::Result<Self> {
        jsonwebtoken8::DecodingKey::from_ec_pem(key).map(|inner| DecodingKey {
            inner,
            material: KeyMaterial::Pem(key.to_vec()),
        })
    }

    pub fn from_ec_der(der: &[u8]) -> Self {
        DecodingKey {
            inner: jsonwebtoken8::DecodingKey::from_ec_der(der),
            material: KeyMaterial::SecretOrDer(der.to_vec()),
        }
    }

    pub fn from_ed_pem(key: &[u8]) -> errors::Result<Self> {
        jsonwebtoken8::DecodingKey::from_ed_pem(key).map(|inner| DecodingKey {
            inner,
            material: KeyMaterial::Pem(key.to_vec()),
        })
    }

    pub fn from_ed_der(der: &[u8]) -> Self {
        DecodingKey {
            inner: jsonwebtoken8::DecodingKey::from_ed_der(der),
            material: KeyMaterial::SecretOrDer(der.to_vec()),
        }
    }

    pub fn into_static(self) -> Self {
        self
    }
}

pub fn encode<T: Serialize>(
    header: &Header,
    claims: &T,
    key: &EncodingKey,
) -> errors::Result<String> {
    jsonwebtoken8::encode(header, claims, &key.inner)
}

pub fn decode<T: serde::de::DeserializeOwned>(
    token: &str,
    key: &DecodingKey,
    validation: &Validation,
) -> errors::Result<TokenData<T>> {
    jsonwebtoken8::decode(token, &key.inner, validation)
}
